INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62079350', 62079350, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN TINGGI TATA USAHA NEGARA BANJARMASIN 05', 'Jasa Layanan Konsultan Hukum. 3 Jam Rp.100.000,-', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Selatan, Banjar Baru (Kota)', 28800000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 96, ORANG, @ 300000 )', '1. Jasa Layanan Konsultan Hukum. 3 Jam Rp.100.000,- ( 96, ORANG, @ 300000 );', 'A. Formasi Penerimaan Lembaga pemberi layanan Pos Bantuan Hukum (POSBAKUM) berasal dari : 1. Lembaga Masyarakat sipil penyedia advokasi hukum; 2. Unit kerja advokasi hukum pada organisasi profesi advokat; atau 3. Lembaga konsultasi dan bantuan hukum perguruan tinggi. B. Persyaratan 1. Berbentuk badan hukum dengan melampirkan akta notaris dan terdaftar di Kementerian Hukum dan HAM RI; 2. Berdomisili di wilayah hukum Pengadilan Tinggi Tata Usaha Negara Banjarmasin atau mempunyai perwakilan di wilayah hukum Pengadilan Tinggi Tata Usaha Negara Banjarmasin dengan melampirkan keterangan domisili lembaga; 3. Menyampaikan surat permohonan yang ditandatangani oleh pimpinan/direktur/ketua lembaga dan ditujukan kepada Panitia Seleksi Lembaga Pemberi Layanan Bantuan Hukum Pos Bantuan Hukum (POSBAKUM) Pengadilan Tinggi Tata Usaha Negara Banjarmasin untuk mengikuti seleksi lembaga pemberi layanan Pos Bantuan Hukum (POSBAKUM) pada Pengadilan Tinggi Tata Usaha Negara Banjarmasin Tahun Anggaran 2026; 4. Memiliki Surat Keputusan Menteri Hukum dan HAM RI Tentang Lembaga/Organisasi Bantuan Hukum yang Lulus Verifikasi dan Akreditasi sebagai Pemberi Bantuan Hukum; 5. Memiliki rekening dan NPWP atas nama lembaga; 6. Memiliki minimal 1 (satu) orang Advokat yang dibuktikan dengan Kartu Advokat dan Berita Acara Sumpah Advokat; 7. Memiliki pengalaman dalam menangani perkara dan/atau beracara di Pengadilan; 8. Memiliki staf atau anggota untuk ditugaskan di POSBAKUM Pengadilan Tinggi Tata Usaha Negara Banjarmasin yang bergelar sarjana hukum; 9. Surat Pernyataan Ketua/Pimpinan Lembaga yang menyatakan Ketua/Pimpinan Lembaga bersedia untuk mengikuti Tes Kualifikasi tertulis dan wawancara; 10. Lulus Tes Kualifikasi yang ditetapkan oleh Pengadilan Tinggi Tata Usaha Negara Banjarmasin; 11. Bersedia menandatangani kontrak dan pakta integritas serta menaati segala peraturan perundang-undangan maupun kebijakan yang terkait dengan POSBAKUM Pengadilan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 171637);
