INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64212345', 64212345, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'UPT Logam', 'Belanja Jasa Konsultansi Berorientasi Bidang-Perindustrian dan Perdagangan Belanja Jasa Konsutansi Manajemen Pelatihan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 18084000, 'June 2026', 'BLUD', 1, 1, 'paket', 'Ruang lingkup pekerjaan Jasa Konsultansi Manajemen Pelatihan ini mencakup seluruh tahapan perencanaan, pelaksanaan, hingga pelaporan kegiatan. Lingkup pekerjaan mencakup hal-hal sebagai berikut: a. Analisis Kebutuhan dan Perencanaan upaya Pembinaan • Melakukan identifikasi dan analisis kebutuhan pembinaan • Eksplorasi bentuk pembinaan • Merancang pendekatan pembinaan yang tepat (klasikal, praktik langsung, pendampingan, layanan, coaching) sesuai dengan jenis industri dan tingkat kesiapan sasaran pembinaan. b. Pengelolaan Sarana Pembinaan • Mengelola asset dan material yang diperlukan • merencanakan asset dan material • Mendefinisikan dan mengelola strategi pengadaan asset dan material pembinaan • Menyiapkan sarana dan prasarana c. Identifikasi dan Formulasi Layanan sebagai Sarana pembinaan • Mengidentifikasi layanan yang dibutuhkan oleh sasaran pembinaan PDIN • Mendefinisikan sasaran pembinaan PDIN • Melakukan formulasi bentuk layanan dan sarana yang dibutuhkan d. Memperbanyak jejaring • Eksplorasi jejaring • Membangun komunikasi dengan jejaring dan mitra potensial • Mendefinisikan peluang kerjasama layanan e. Mentransformasi potensi kerjasama menjadi layanan pembinaan • Menyiapkan administrasi kerjasama • Memformulasi bentuk kerjasama • Mendefinisikan ruang lingkup kerjasama • Menyiapkan formulasi analisis kelayakan kerjasama f. Evaluasi dan proyeksi kebutuhan kedepan • Melakukan proyeksi bentuk pembinaan pasca layanan • Mengembangkan bisnis layanan • Mendefinisikan bentuk layanan sebagai bentuk advance dari layanan eksisting • Menyiapkan kelayakan layanan baru secara ekonomi dan bisnis g. Penyusunan Laporan Akhir dan Evaluasi • Menyusun laporan pelaksanaan kegiatan, evaluasi dan dokumentasi visual (foto/video) • Laporan ini akan menjadi bagian dari pertanggungjawaban pelaksanaan belanja jasa konsultansi. • Melakukan Evaluasi menyeluruh terkait dengan pelaksanaan pekerjaan yang telah dilaksanakan serta memberikan Rekomendasi perbaikan dan optimasi strategi', 'ada dalam KAK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 172843);
