INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62085077', 62085077, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Langganan Jaringan Telepon Kantor Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 2160000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12.0 Bulan', 'Pekerjaan ini mencakup penyediaan layanan langganan jaringan telepon kantor untuk mendukung kelancaran komunikasi kedinasan pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 yang dilaksanakan selama 12 (dua belas) bulan dalam 1 (satu) Tahun Anggaran. Layanan disediakan secara berkesinambungan guna menunjang pelaksanaan tugas dan fungsi pengawasan serta administrasi perkantoran. Ruang lingkup pekerjaan meliputi penyediaan sambungan jaringan telepon tetap kantor, ketersediaan layanan sesuai standar layanan telekomunikasi.', 'Layanan langganan jaringan telepon kantor disediakan untuk memenuhi kebutuhan komunikasi kedinasan Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 secara andal, berkesinambungan, dan sesuai standar layanan telekomunikasi. Jenis layanan berupa langganan jaringan telepon tetap kantor yang dapat digunakan untuk komunikasi lokal, interlokal, dan kebutuhan komunikasi kedinasan lainnya. Layanan mencakup penyediaan sambungan aktif, pengelolaan nomor telepon, serta akses jaringan selama masa kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 175792);
