INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62087454', 62087454, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Jasa Pihak Ketiga Tenaga Alih Daya Berupa Pramubakti dan Pengemudi/Supir Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 257830000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 PAKET', 'Pekerjaan ini mencakup penyediaan jasa pihak ketiga berupa tenaga alih daya pramubakti dan pengemudi/supir untuk mendukung kelancaran operasional Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026. Layanan disediakan secara profesional, berkesinambungan, dan sesuai dengan kebutuhan kegiatan perkantoran dan kedinasan. Ruang lingkup pekerjaan meliputi penyediaan tenaga pramubakti yang bertugas membantu pelaksanaan kegiatan administrasi, pelayanan perkantoran, penataan dan kebersihan area kerja, serta dukungan operasional lainnya sesuai penugasan. Selain itu, penyediaan tenaga pengemudi/supir meliputi pengoperasian kendaraan dinas untuk mendukung mobilitas pimpinan dan pegawai dalam pelaksanaan tugas kedinasan. Penyedia bertanggung jawab atas rekrutmen, penempatan, pengelolaan, dan pembinaan tenaga alih daya sesuai kualifikasi yang dipersyaratkan. Penyedia wajib memastikan tenaga yang ditugaskan memiliki kompetensi, disiplin, etika kerja, serta mematuhi ketentuan jam kerja dan tata tertib yang berlaku di lingkungan Inspektorat Jenderal', 'Tenaga alih daya yang disediakan terdiri atas pramubakti dan pengemudi/supir. Seluruh tenaga kerja harus berkewarganegaraan Indonesia, berusia 22–55 tahun, dan berpendidikan minimal SMA/SMK. Tenaga pramubakti wajib memiliki pengalaman kerja paling singkat 1 (satu) tahun sebagai pramusaji, pramubakti, atau office boy. Tenaga pengemudi/supir wajib memiliki pengalaman kerja paling singkat 1 (satu) tahun sebagai pengemudi. Komponen biaya telah mencakup gaji atau upah, BPJS Ketenagakerjaan, BPJS Kesehatan, tunjangan, serta pakaian kerja. Seluruh tenaga kerja wajib mematuhi ketentuan dan tata tertib yang berlaku di lingkungan Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 178704);
