INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62088761', 62088761, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA MUNGKID 04', 'Pengadaan Jasa Konsultansi Layanan Pos Bantuan Hukum pada Pengadilan Agama Mungkid Tahun 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Tengah, Magelang (Kab.)', 84000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Memberikan layanan berupa: 1. Pemberian informasi, konsultasi, atau advis hukum 2. Bantuan pembuatan dokumen hukum yang dibutuhkan 3. Penyediaan informasi daftar Organisasi Bantuan Hukum sebagaimana dimaksud dalam UU No. 16 tahun 2011 Tentang Bantuan Hukum atau organisasi bantuan hukum atau advokat lainnya yang dapat memberikan bantuan hukum cuma-cuma.', 'Standar Layanan Posbakum Pengadilan adalah: 1. Memberikan layanan yang profesional dan bertanggung jawab. Dimana profesional yang dimaksud adalah bersungguh-sungguh dalam memberikan layanan berdasarkan keahlian, kompetensi, wawasan dan tingkat pendidikan Pemberi Layanan Posbakum Pengadilan sebagai orang yang telah memiliki izin advokat atau gelar Sarjana Hukum atau gelar Sarjana Syariah. Sedangkan bertanggung jawab adalah memberikan layanan yang berdasarkan pada ilmu pengetahuan hukum, naik hukum materiil maupun hukum formil secara sebaik-baiknya dan bersedia menanggung akibat dari pelaksanaan layanan yang diberikan. 2. Memberikan informasi hukum dan informasi lain yang terkait secara jelas dan akurat 3. Memberikan konsultasi atau advis hukum yang seimbang dan komperehensif. Dimana seimbang adalah mengutamakan kepentingan Penerima Layanan Posbakum Pengadilan untuk mencapai keadilan, tanpa menjatuhkan pihak lain atau menggunakan cara-cara yang tidak dibenarkan secara hukum. Sedangkan komperehensif adalah memberikan konsultasi atau advis hukum yang memperhatikan segala aspek dari hukum materiil maupun hukum formil sehingga Penerima Layanan Posbakum Pengadilan dapat mencapai keadilan yang sebaik-baiknya dalam menjalankan perkaranya. 4. Merahasiakan segala sesuatu yang diketahui atau diperoleh dari Penerima Layanan Posbakum Pengadilan. 5. Menjalankan prinsip-prinsip perlindungan terhadap penyandang disabilitas, perempuan, anak-anak, dan orang lanjut usia. 6. Menghindari konflik kepentingan dengan Penerima Layanan Posbakum Pengadilan 7. Membuat laporan dan mendokumentasikan berkas Penerima Layanan Posbakum Pengadilan untuk diserahkan kepada Ketua Pengadilan. 8. Bekerja sama dengan petugas Pengadilan yang ditunjuk Ketua Pengadilan dalam menjaga dan memelihara ketertiban penyelenggaraan dan sarana dan prasarana Posbakum Pengadilan. 9. Kepala Lembaga Pemberi Layanan Posbakum Pengadilan melakukan pengawasan bersama-sama dengan Ketua Pengadilan terhadap kualitas layanan yang diberikan Petugas Posbakum Pengadilan dari lembaganya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 178755);
