INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62090182', 62090182, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Alat Tulis Kantor Dalam Kegiatan Keperluan Perkantoran Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 393889000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 PAKET', 'Pekerjaan ini meliputi pengadaan alat tulis kantor untuk mendukung kegiatan administrasi dan operasional perkantoran pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026. Pengadaan dilakukan untuk menjamin ketersediaan perlengkapan kerja secara rutin dan berkelanjutan selama 1 (satu) tahun anggaran. Ruang lingkup pekerjaan mencakup penyediaan berbagai jenis alat tulis kantor dan perlengkapan administrasi, antara lain perlengkapan menulis, perlengkapan kertas, perlengkapan pengarsipan, serta perlengkapan pendukung administrasi lainnya sesuai rencana kebutuhan bulanan. Pengadaan dilakukan berdasarkan volume kebutuhan yang telah ditetapkan dengan pola distribusi bulanan selama 12 (dua belas) bulan. Penyedia bertanggung jawab atas pengadaan, pengemasan, dan pengiriman seluruh barang ke lokasi yang ditentukan sesuai jadwal kebutuhan. Seluruh barang yang disediakan harus baru, layak pakai, dan sesuai peruntukan kegiatan perkantoran', 'Pengadaan Alat Tulis Kantor (ATK) dilaksanakan untuk memenuhi kebutuhan operasional perkantoran Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 selama 1 (satu) tahun anggaran. Jenis barang yang disediakan meliputi perlengkapan tulis, perlengkapan kertas, perlengkapan pengarsipan, dan perlengkapan pendukung administrasi lainnya sesuai daftar kebutuhan, antara lain spidol permanen dan boardmarker berbagai warna, pulpen, pensil, stabilo, penghapus, rautan, penggaris, kalkulator, cutter dan isi cutter, gunting, lem kertas, lakban, stapler dan isi staples, pembolong kertas, sticky notes, correction tape, binder clip, paper clip, serta gantungan kunci. Selain itu, pengadaan mencakup berbagai jenis kertas dan perlengkapan arsip berupa kertas A4, F4, A5, kertas berwarna, kertas concorde, label, sign here, amplop kabinet, map plastik, map kertas, ordner, box file, buku folio, buku ekspedisi, dan perlengkapan sejenis lainnya. Seluruh barang harus merupakan produk baru, berkualitas baik, tidak cacat, dan layak pakai, serta memenuhi standar umum alat tulis kantor. Jumlah dan satuan barang disesuaikan dengan kebutuhan bulanan selama 12 (dua belas) bulan sebagaimana tercantum dalam rencana kebutuhan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 179000);
